#include <jyppx/liuding/vision/models/extended/open_vocabulary.hpp>
#include "../yolo/blocks.hpp"
#include <torch/torch.h>
namespace jyppx::liuding::models::extended {
namespace {
using I=std::int64_t;namespace yd=yolo::detail;
Tensor Normal(const Tensor& x,I axis){return x/x.square().sum(axis,true).sqrt().clamp_min(1e-12);}
Tensor Resize(const Tensor& x,const Tensor& y){return torch::nn::functional::interpolate(x,torch::nn::functional::InterpolateFuncOptions().size(std::vector<I>{y.size(2),y.size(3)}).mode(torch::kNearest));}
struct NeckBlock:torch::nn::Module {
  yd::U split,tail,projection,embed;std::vector<yd::U> blocks;torch::nn::Linear guide{nullptr};Tensor bias;I hidden,heads;bool guided;
  NeckBlock(I in,I out,I n,bool text):hidden(out/2),heads((std::max)(I{1},out/64)),guided(text){split=register_module("cv1",yd::C(in,hidden*2));tail=register_module("cv2",yd::C((n+(text?3:2))*hidden,out));for(I k=0;k<n;++k)blocks.push_back(register_module("bottleneck"+std::to_string(k),std::make_shared<yd::Bottleneck>(hidden,hidden,false,1.)));
    if(text){embed=register_module("embed",yd::C(hidden,hidden,1,1,1,false));projection=register_module("projection",yd::C(hidden,hidden,3,1,1,false));guide=register_module("guide",torch::nn::Linear(512,hidden));bias=register_parameter("bias",torch::zeros({heads}));}}
  Tensor forward(const Tensor& image,const Tensor& text){auto x=split->run(image).chunk(2,1);for(auto& b:blocks)x.push_back(b->run(x.back()));if(guided){auto f=embed->run(x.back());I b=f.size(0),h=f.size(2),w=f.size(3),d=hidden/heads;auto q=f.view({b,heads,d,h*w}).transpose(2,3);auto k=guide(text).view({b,text.size(1),heads,d}).permute({0,2,3,1});auto score=std::get<0>(q.matmul(k).max(-1))/std::sqrt(static_cast<double>(d));auto gate=(score+bias.view({1,heads,1})).sigmoid().view({b,heads,1,h,w});x.push_back((projection->run(x.back()).view({b,heads,d,h,w})*gate).reshape({b,hidden,h,w}));}return tail->run(torch::cat(x,1));}
};
struct SpatialVisual:torch::nn::Module {
  std::array<yd::U,3> dense,spatial;torch::nn::Conv2d values{nullptr},features{nullptr},mask{nullptr},last{nullptr};yd::U fuse;
  SpatialVisual(){std::array<I,3> channels{128,256,512};for(I i=0;i<3;++i){dense[i]=register_module("dense"+std::to_string(i),std::make_shared<yd::Chain>(std::vector<yd::U>{yd::C(channels[i],128,3),yd::C(128,128,3)}));spatial[i]=register_module("spatial"+std::to_string(i),yd::C(channels[i],128));}values=register_module("values",torch::nn::Conv2d(torch::nn::Conv2dOptions(384,512,1)));features=register_module("features",torch::nn::Conv2d(torch::nn::Conv2dOptions(384,16,3).padding(1)));mask=register_module("mask",torch::nn::Conv2d(torch::nn::Conv2dOptions(1,16,3).padding(1)));fuse=register_module("fuse",yd::C(32,16,3));last=register_module("last",torch::nn::Conv2d(torch::nn::Conv2dOptions(16,16,3).padding(1)));}
  Tensor forward(const std::vector<Tensor>& x,const Tensor& masks){I b=x[0].size(0),n=masks.size(1),h=x[0].size(2),w=x[0].size(3);if(b*n*h*w*16>33554432)throw ResourceExhausted("Visual prompt attention budget exceeded");std::vector<Tensor> f,g;for(I i=0;i<3;++i){f.push_back(Resize(dense[i]->run(x[i]),x[0]));g.push_back(Resize(spatial[i]->run(x[i]),x[0]));}auto value=values(torch::cat(f,1)).view({b,16,32,h*w});auto image=features(torch::cat(g,1)).unsqueeze(1).expand({b,n,16,h,w}).reshape({b*n,16,h,w});auto vp=masks.reshape({b*n,1,h,w});auto score=last(fuse->run(torch::cat({image,mask(vp)},1))).view({b,n,16,h*w});score=score.masked_fill(masks.reshape({b,n,1,h*w})<=0,-1e4).softmax(-1);auto aggregated=score.permute({0,2,1,3}).matmul(value.transpose(2,3)).permute({0,2,1,3}).reshape({b,n,512});return Normal(aggregated,-1);}
};
}
struct OpenVocabularyImpl::Impl:torch::nn::Module {
  OpenVocabularyOptions o;std::vector<yd::U> backbone;std::array<std::shared_ptr<NeckBlock>,4> neck;std::array<yd::U,2> down;std::array<yd::U,3> box,embedding,coefficients;std::array<torch::nn::BatchNorm2d,3> normalization{nullptr,nullptr,nullptr};std::array<torch::nn::Conv2d,3> filter{nullptr,nullptr,nullptr};std::array<Tensor,3> scale,bias;torch::nn::Linear w12{nullptr},w3{nullptr};Tensor vocabulary;std::shared_ptr<SpatialVisual> visual;yd::U proto_a,proto_b;torch::nn::ConvTranspose2d proto_up{nullptr};torch::nn::Conv2d proto_out{nullptr};
  explicit Impl(OpenVocabularyOptions options):o(options){if(o.num_classes<1||o.num_classes>1024||o.embedding!=512||o.mask_channels<1||o.mask_channels>256)throw InvalidArgument("Invalid native open-vocabulary options");bool world=o.mode==PromptMode::world_text;
    std::vector<yd::U> units{yd::C(3,32,3,2),yd::C(32,64,3,2),std::make_shared<yd::Csp>(64,64,1,true,"C2f"),yd::C(64,128,3,2),std::make_shared<yd::Csp>(128,128,2,true,"C2f"),yd::C(128,256,3,2),std::make_shared<yd::Csp>(256,256,2,true,"C2f"),yd::C(256,512,3,2),std::make_shared<yd::Csp>(512,512,1,true,"C2f"),std::make_shared<yd::Sppf>(512,512,5,3,false,true)};
    for(std::size_t i=0;i<units.size();++i)backbone.push_back(register_module("backbone"+std::to_string(i),units[i]));std::array<I,4> in{768,384,384,768},out{256,128,256,512};for(I i=0;i<4;++i)neck[i]=register_module("neck"+std::to_string(i),std::make_shared<NeckBlock>(in[i],out[i],1,world));down[0]=register_module("down0",yd::C(128,128,3,2));down[1]=register_module("down1",yd::C(256,256,3,2));
    std::array<I,3> channels{128,256,512};for(I i=0;i<3;++i){box[i]=register_module("box"+std::to_string(i),std::make_shared<yd::Chain>(std::vector<yd::U>{yd::C(channels[i],64,3),yd::C(64,64,3)}));auto last=register_module("box_out"+std::to_string(i),torch::nn::Conv2d(torch::nn::Conv2dOptions(64,64,1)));box_output.push_back(last);embedding[i]=register_module("embedding"+std::to_string(i),std::make_shared<yd::Chain>(std::vector<yd::U>{yd::C(channels[i],128,3),yd::C(128,128,3)}));embed_output.push_back(register_module("embedding_out"+std::to_string(i),torch::nn::Conv2d(torch::nn::Conv2dOptions(128,512,1))));normalization[i]=register_module("contrastive_norm"+std::to_string(i),torch::nn::BatchNorm2d(512));scale[i]=register_parameter("logit_scale"+std::to_string(i),torch::ones({})*-1.);bias[i]=register_parameter("logit_bias"+std::to_string(i),torch::ones({})*-10.);filter[i]=register_module("proposal_filter"+std::to_string(i),torch::nn::Conv2d(torch::nn::Conv2dOptions(512,1,1)));
      if(o.segmentation){coefficients[i]=register_module("coefficient"+std::to_string(i),std::make_shared<yd::Chain>(std::vector<yd::U>{yd::C(channels[i],o.mask_channels,3),yd::C(o.mask_channels,o.mask_channels,3)}));coefficient_out.push_back(register_module("coefficient_out"+std::to_string(i),torch::nn::Conv2d(torch::nn::Conv2dOptions(o.mask_channels,o.mask_channels,1))));}}
    if(!world){w12=register_module("reprta_w12",torch::nn::Linear(512,2048));w3=register_module("reprta_w3",torch::nn::Linear(1024,512));torch::NoGradGuard guard;w3->weight.zero_();w3->bias.zero_();}if(o.mode==PromptMode::yoloe_visual)visual=register_module("savpe",std::make_shared<SpatialVisual>());if(o.mode==PromptMode::yoloe_prompt_free)vocabulary=register_parameter("vocabulary",Normal(torch::randn({o.num_classes,512}),-1));
    if(o.segmentation){proto_a=register_module("proto_a",yd::C(128,256,3));proto_up=register_module("proto_up",torch::nn::ConvTranspose2d(torch::nn::ConvTranspose2dOptions(256,256,2).stride(2)));proto_b=register_module("proto_b",yd::C(256,256,3));proto_out=register_module("proto_out",torch::nn::Conv2d(torch::nn::Conv2dOptions(256,o.mask_channels,1)));}}
  std::vector<torch::nn::Conv2d> box_output,embed_output,coefficient_out;
  std::vector<Tensor> forward(const Tensor& images,const Tensor& prompt,const Tensor& masks){if(images.dim()!=4||images.size(0)<1||images.size(0)>32||images.size(1)!=3||images.size(2)<32||images.size(3)<32||images.size(2)%32||images.size(3)%32||images.numel()>50331648)throw InvalidArgument("Invalid open-vocabulary image contract");I b=images.size(0);Tensor text=prompt;
    if(o.mode==PromptMode::world_text||o.mode==PromptMode::yoloe_text){if(text.sizes()!=torch::IntArrayRef({b,o.num_classes,512})||text.device()!=images.device()||!torch::isfinite(text).all().item<bool>()||!(text.square().sum(-1)>0).all().item<bool>())throw InvalidArgument("Prompt embeddings must match complete class vocabulary and image device");if(o.mode==PromptMode::yoloe_text){auto pair=w12(text.reshape({-1,512})).view({b,o.num_classes,2048}).chunk(2,-1);text=text+w3((torch::silu(pair[0])*pair[1]).reshape({-1,1024})).view({b,o.num_classes,512});}text=Normal(text,-1);}
    else if(o.mode==PromptMode::yoloe_prompt_free)text=Normal(vocabulary,-1).unsqueeze(0).expand({b,-1,-1});else text=torch::empty({b,0,512},images.options());
    std::vector<Tensor> features;auto x=images;for(I i=0;i<10;++i){x=backbone[i]->run(x);if(i==4||i==6||i==9)features.push_back(x);}auto p4=neck[0]->forward(torch::cat({Resize(features[2],features[1]),features[1]},1),text);auto p3=neck[1]->forward(torch::cat({Resize(p4,features[0]),features[0]},1),text);p4=neck[2]->forward(torch::cat({down[0]->run(p3),p4},1),text);auto p5=neck[3]->forward(torch::cat({down[1]->run(p4),features[2]},1),text);features={p3,p4,p5};
    if(o.mode==PromptMode::yoloe_visual){if(masks.sizes()!=torch::IntArrayRef({b,o.num_classes,p3.size(2),p3.size(3)})||masks.device()!=images.device()||!torch::isfinite(masks).all().item<bool>()||!(masks.flatten(2).sum(-1)>0).all().item<bool>()||masks.min().item<double>()<0||masks.max().item<double>()>1)throw InvalidArgument("Visual prompt masks must be nonempty for every image/class");text=visual->forward(features,masks);}
    std::vector<Tensor> raw,filters;for(I i=0;i<3;++i){auto f=normalization[i](embed_output[i](embedding[i]->run(features[i])));auto cls=torch::bmm(text,f.flatten(2))*scale[i].exp()+bias[i];auto proposal=filter[i](f).flatten(2);if(o.mode!=PromptMode::yoloe_prompt_free)proposal=proposal*0;else if(!is_training())cls=cls.masked_fill(proposal.sigmoid()<.001,-30.);std::vector<Tensor> chunks{box_output[i](box[i]->run(features[i])).flatten(2),cls};if(o.segmentation)chunks.push_back(coefficient_out[i](coefficients[i]->run(features[i])).flatten(2));raw.push_back(torch::cat(chunks,1));filters.push_back(proposal);}
    auto prediction=torch::cat(raw,2);if(prediction.numel()>67108864)throw ResourceExhausted("Open-vocabulary output budget exceeded");auto prototypes=o.segmentation?proto_out(proto_b->run(proto_up(proto_a->run(p3)))):torch::empty({b,0,images.size(2)/4,images.size(3)/4},images.options());return{prediction,prototypes,torch::cat(filters,2)};}
};
OpenVocabularyImpl::OpenVocabularyImpl(OpenVocabularyOptions o){impl_=register_module("model",std::make_shared<Impl>(o));}OpenVocabularyImpl::~OpenVocabularyImpl()=default;std::vector<Tensor> OpenVocabularyImpl::forward(const Tensor& x,const Tensor& p,const Tensor& m){return impl_->forward(x,p,m);}
void OpenVocabularyImpl::set_vocabulary(const Tensor& x){if(is_training()||impl_->o.mode!=PromptMode::yoloe_prompt_free||x.sizes()!=impl_->vocabulary.sizes()||!torch::isfinite(x).all().item<bool>()||!(x.square().sum(-1)>0).all().item<bool>())throw InvalidArgument("Vocabulary copy needs eval prompt-free profile and matching nonzero embeddings");torch::NoGradGuard guard;impl_->vocabulary.copy_(Normal(x.to(impl_->vocabulary.options()),-1));}
nn::ModelAdapter adapt(OpenVocabulary model){return nn::adapt_holder(model,[](OpenVocabularyImpl& m,const nn::Invocation& x){auto out=m.forward(x.positional[0].toTensor(),x.positional[1].toTensor(),x.positional[2].toTensor());return c10::ivalue::Tuple::create({out[0],out[1],out[2]});},{.positional={ValueSchema::tensor({}),ValueSchema::tensor({}),ValueSchema::tensor({})},.keyword={},.allow_extra_keywords=false},ValueSchema::tuple({ValueSchema::tensor({}),ValueSchema::tensor({}),ValueSchema::tensor({})}));}
}
